{
  "name": "Fluke 3000 FC 无线测量系统",
  "name_en": "Fluke 3000 FC Wireless Measurement System",
  "manufacturer": "Fluke",
  "description": "Fluke 3000 FC 是一套通过 PC3000 无线适配器与计算机通信的无线测量仪器系统，可包含 3000 FC 无线数字万用表以及温度、电压等测量模块。它适用于实验室中对电压、温度等信号进行远程读取与数据采集。",
  "description_en": "The Fluke 3000 FC is a wireless measurement instrument system that communicates with a computer through a PC3000 wireless adapter. It can include the 3000 FC wireless digital multimeter as well as temperature and voltage measurement modules, and is used in laboratories for remote readout and acquisition of quantities such as voltage and temperature.",
  "tag_hints": [
    "wireless multimeter",
    "PC3000 adapter",
    "remote electrical measurement",
    "temperature measurement",
    "digital multimeter",
    "voltage measurement"
  ],
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接并绑定可用的无线测量模块。",
      "description_en": "Connect to and bind available wireless measurement modules."
    },
    {
      "action_name": "auto-flush",
      "description": "清空适配器的串口输入缓冲区。",
      "description_en": "Flush the serial input buffer of the adapter."
    },
    {
      "action_name": "auto-measure",
      "description": "按指定测量模式执行一次读数。",
      "description_en": "Perform a measurement readout in the specified measurement mode."
    },
    {
      "action_name": "auto-query_lines",
      "description": "向设备发送查询并读取多行响应。",
      "description_en": "Send a query to the device and read a multiline response."
    },
    {
      "action_name": "auto-read_lines",
      "description": "读取设备返回的一行或多行数据。",
      "description_en": "Read one or more lines of data returned by the device."
    },
    {
      "action_name": "auto-reset",
      "description": "复位系统并解除已绑定模块。",
      "description_en": "Reset the system and unbind connected modules."
    },
    {
      "action_name": "auto-scan",
      "description": "扫描并识别可用的无线测量模块。",
      "description_en": "Scan for and identify available wireless measurement modules."
    },
    {
      "action_name": "auto-mode",
      "description": "获取万用表测量模式。",
      "description_en": "Get the multimeter measurement mode."
    },
    {
      "action_name": "auto-trigger_mode",
      "description": "获取万用表触发模式。",
      "description_en": "Get the multimeter trigger mode."
    },
    {
      "action_name": "auto-relative",
      "description": "获取相对测量模式状态。",
      "description_en": "Get the status of relative measurement mode."
    },
    {
      "action_name": "auto-input_range",
      "description": "获取当前输入量程设置。",
      "description_en": "Get the current input range setting."
    }
  ]
}

